// VIBS retorna o valor total consolidado do IBS se informado.
func (t *IBSCBSTot) VIBS() Decimal {
	if t != nil && t.GIBS != nil {
		return t.GIBS.VIBS
	}
	return NewDecimal("0.00")
}

// VCBS retorna o valor total consolidado da CBS se informado.
func (t *IBSCBSTot) VCBS() Decimal {
	if t != nil && t.GCBS != nil {
		return t.GCBS.VCBS
	}
	return NewDecimal("0.00")
}

