// Signature representa a assinatura digital XMLDSig W3C.
type Signature struct {
	XMLName        xml.Name   `xml:"http://www.w3.org/2000/09/xmldsig# Signature" json:"-"`
	SignedInfo     SignedInfo `xml:"SignedInfo" json:"signedInfo"`
	SignatureValue string     `xml:"SignatureValue" json:"signatureValue"`
	KeyInfo        KeyInfo    `xml:"KeyInfo" json:"keyInfo"`
}

type SignedInfo struct {
	CanonicalizationMethod C14NMethod `xml:"CanonicalizationMethod" json:"canonicalizationMethod"`
	SignatureMethod        SigMethod  `xml:"SignatureMethod" json:"signatureMethod"`
	Reference              Reference  `xml:"Reference" json:"reference"`
}

type C14NMethod struct {
	Algorithm string `xml:"Algorithm,attr" json:"algorithm"`
}

type SigMethod struct {
	Algorithm string `xml:"Algorithm,attr" json:"algorithm"`
}

type Reference struct {
	URI          string       `xml:"URI,attr" json:"uri"`
	Transforms   Transforms   `xml:"Transforms" json:"transforms"`
	DigestMethod DigestMethod `xml:"DigestMethod" json:"digestMethod"`
	DigestValue  string       `xml:"DigestValue" json:"digestValue"`
}

type Transforms struct {
	Transform []Transform `xml:"Transform" json:"transform"`
}

type Transform struct {
	Algorithm string `xml:"Algorithm,attr" json:"algorithm"`
}

type DigestMethod struct {
	Algorithm string `xml:"Algorithm,attr" json:"algorithm"`
}

type KeyInfo struct {
	X509Data X509Data `xml:"X509Data" json:"x509Data"`
}

type X509Data struct {
	X509Certificate string `xml:"X509Certificate" json:"x509Certificate"`
}
